use std :: collections :: BTreeMap ; use std :: ops :: Deref ; use derive_more :: { Deref , Display , From } ; use derive_setters :: Setters ; use merge :: Merge ; use serde :: { Deserialize , Serialize } ; use strum_macros :: { Display as StrumDisplay , EnumIter , EnumString } ; use serde :: de ; use std :: hash :: { Hash , Hasher } ; use super :: * ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_ne ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use fake :: { Fake , Faker } ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; impl McpTrustStore { # [doc = " Returns true if the given path+hash pair has been previously accepted."] pub fn is_trusted (& self , path : & std :: path :: Path , content_hash : u64) -> bool { self . trusted . get (& path . to_string_lossy () . into_owned ()) . is_some_and (| & stored | stored == content_hash) } # [doc = " Returns true if the given path+hash pair has been previously rejected."] pub fn is_rejected (& self , path : & std :: path :: Path , content_hash : u64) -> bool { self . rejected . get (& path . to_string_lossy () . into_owned ()) . is_some_and (| & stored | stored == content_hash) } # [doc = " Records an accepted trust decision for the given path and content hash."] # [doc = " Clears any prior rejection for the same path."] pub fn remember (& mut self , path : std :: path :: PathBuf , content_hash : u64) { let key = path . to_string_lossy () . into_owned () ; self . rejected . remove (& key) ; self . trusted . insert (key , content_hash) ; } # [doc = " Records a rejected trust decision for the given path and content hash."] # [doc = " Clears any prior acceptance for the same path."] pub fn reject (& mut self , path : std :: path :: PathBuf , content_hash : u64) { let key = path . to_string_lossy () . into_owned () ; self . trusted . remove (& key) ; self . rejected . insert (key , content_hash) ; } }